from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx',data_only=False)
data=wb['Data']
print('Data rows 1-20 columns A-L:')
for r in range(1,21):
    vals=[data.cell(r,c).value for c in range(1,13)]
    if any(v is not None for v in vals):
        print(r, [f'{get_column_letter(c)}={data.cell(r,c).value!r}' for c in range(1,13)])
print('\nAll non-empty cells in Data rows 1-20:')
for r in range(1,21):
    cells=[]
    for c in range(1,data.max_column+1):
        v=data.cell(r,c).value
        if v is not None:
            cells.append(f'{get_column_letter(c)}{r}={v!r}')
    if cells:
        print('; '.join(cells))
